#include <vector>
#include <algorithm>
#include <unordered_set>

using namespace std;

class Solution {
public:
    int maxSum(vector<int>& nums) {
        int mx = *max_element(nums.begin(), nums.end());
        if (mx <= 0) {
            return mx;
        }

        unordered_set<int> uniquePositives;
        int sum = 0;
        for (int x : nums) {
            if (x > 0 && uniquePositives.insert(x).second) {
                sum += x;
            }
        }
        return sum;
    }
};

import java.util.*;

class Solution {
    public int maxSum(int[] nums) {
        int mx = Integer.MIN_VALUE;
        for (int x : nums) {
            if (x > mx) mx = x;
        }
        if (mx <= 0) return mx;

        Set<Integer> uniquePositives = new HashSet<>();
        int sum = 0;
        for (int x : nums) {
            if (x > 0 && uniquePositives.add(x)) {
                sum += x;
            }
        }
        return sum;
    }
}

var maxSum = function(nums) {
    let mx = -Infinity;
    for (const x of nums) {
        if (x > mx) mx = x;
    }
    if (mx <= 0) return mx;

    const uniquePositives = new Set();
    let sum = 0;
    for (const x of nums) {
        if (x > 0 && !uniquePositives.has(x)) {
            uniquePositives.add(x);
            sum += x;
        }
    }
    return sum;
};
